import {measureAudio} from './audio-certification.js';import {measureLoudness} from './audio-loudness.js';
const rack=(id,name,mode,processing,rate,bits,tail,dither,description)=>({id,name,mode,processing,rate,bits,tail,dither,description});
export const EXPORT_RACKS=[rack('single','Single / WAV 24','mix','wet',44100,24,true,false,'Stereo master; confirm distributor sample-rate requirements.'),rack('radio','Radio / WAV 48 kHz','mix','wet',48000,24,true,false,'Radio delivery format, not a radio edit or a guaranteed loudness target.'),rack('premaster','Premaster / float','mix','wet',48000,32,true,false,'Includes current master: bypass limiting manually if requested.'),rack('stems','Stems / wet','stems','wet',48000,24,true,false,'Wet stems before master; identical duration.'),rack('stems-clean','Stems / clean','stems','clean',48000,24,false,false,'Dry stems before master; no inserts.'),rack('bus','Bus stems','buses','wet',48000,24,true,false,'Routed buses, before master.'),rack('track','Selected track / WAV','track','wet',48000,24,true,false,'Selected source or bus only.'),rack('cd','CD / PCM 16','mix','wet',44100,16,true,true,'Dither for final 16-bit PCM.')];
const fmt=x=>Number.isFinite(x)?Number(x.toFixed(2)):null;
export function inspectExportRender(buffer,{allowSilence=false}={}){const m=measureAudio(buffer),issues=[];if(m.invalid)issues.push('non-finite PCM');if(m.clipped||m.peakDb>=0)issues.push('sample peak at or above full scale');if(!allowSilence&&m.peakDb===-Infinity)issues.push('silent render');let loud={};if(!m.invalid&&[1,2].includes(buffer.numberOfChannels)&&buffer.sampleRate>=32000)loud=measureLoudness(buffer);return {status:issues.length?'blocked':Number.isFinite(loud.truePeakDb)&&loud.truePeakDb>0?'review true peak':'measured',issues,peakDb:fmt(m.peakDb),lufs:fmt(loud.integrated),truePeakDb:fmt(loud.truePeakDb),normativeCertified:false};}